def to_markdown(rows):
    """Render rows (a list of lists of strings, header first) as a GitHub markdown table."""
    if not rows:
        raise ValueError("no rows")
    header = rows[0]
    if not header:
        raise ValueError("empty header")
    width = len(header)
    lines = []
    for i, row in enumerate(rows):
        if len(row) != width:
            raise ValueError(f"row {i} has {len(row)} cells, header has {width}")
        cells = [cell.strip().replace("|", "\\|") for cell in row]
        lines.append("| " + " | ".join(cells) + " |")
        if i == 0:
            lines.append("| " + " | ".join("---" for _ in header) + " |")
    return "\n".join(lines)

